def extend(cities):
    """Nối NEW vào danh sách và gắn META cho điểm cũ (gọi từ intl_src.py)."""
    for c in cities:
        base = len(c['places'])
        if c.get('_ext'):
            continue
        out = []
        for i, p in enumerate(c['places']):
            extra = dict(p[4]) if len(p) > 4 else {}
            extra.update(META.get(f"{c['id']}-{i + 1}", {}))
            out.append((p[0], p[1], p[2], p[3], extra))
        out += [(p[0], p[1], p[2], p[3], dict(p[4])) for p in NEW.get(c['id'], [])]
        c['places'] = out
        c['_ext'] = base
    return cities
